window.CARDS=window.CARDS||{};CARDS["people-tsubaki-sakurako"]=[{"i":"sc-tsubaki-sakurako-y2v1-p268-1","v":"y2v1","y":2,"o":16,"k":"","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako ch 5  seeking a partner approaches ayanokoji at keyaki mall with utomiya  explains she hasn t found a partner yet  leaves to search elsewhere  searches with him  approaches him","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v1-p268-1\"><h3><span class=\"ttl\">Ch.5: Seeking a partner<\/span><span class=\"meta\">Y2V1 · p.268–275<\/span><\/h3><p class=\"setup\">Approaches Ayanokōji at Keyaki Mall with Utomiya. Explains she hasn’t found a partner yet. Leaves to search elsewhere.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Searches with him.<span class=\"pg\">p.268–275<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him.<span class=\"pg\">p.268–275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-2\">→ After: Epilogue: Seeking a partner<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v1-p268-2","v":"y2v1","y":2,"o":16,"k":"","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako epilogue  seeking a partner approaches ayanokoji at keyaki mall  leaves to search elsewhere  searches with him  approaches him","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v1-p268-2\"><h3><span class=\"ttl\">Epilogue: Seeking a partner<\/span><span class=\"meta\">Y2V1 · p.268–275<\/span><\/h3><p class=\"setup\">Approaches Ayanokōji at Keyaki Mall. Leaves to search elsewhere.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Searches with him.<span class=\"pg\">p.268–275<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him.<span class=\"pg\">p.268–275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-1\">← Before: Ch.5: Seeking a partner<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-3\">→ After: Tsubaki and Utomiya approach Ayanokōji about partnering<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v1-p268-3","v":"y2v1","y":2,"o":16,"k":"narration spoken","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako tsubaki and utomiya approach ayanokoji about partnering on the walk back from keyaki mall  she and utomiya riku  class 1 c  call out to ayanokoji  she repeatedly checks her phone  the oaa app   i m utomiya  and her name is tsubaki  could we talk with you for a bit about becoming partners for this special exam   we re currently going around searching for upperclassmen with academic ability ratings of a c or higher who are willing to cooperate with us   you re class 2 d s  ayanokoji senpai  correct    tsubaki a class 1 c first year with a c  academic rating  still unpaired  she and utomiya seek a c or higher upperclassman  and propose moving to a cafe to discuss   a timing that strikes ayanokoji as  far too good to be true  her classmate  he spearheads the conversation and already has a partner  approaches him about partnering  he is wary the encounter was arranged","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v1-p268-3\"><h3><span class=\"ttl\">Tsubaki and Utomiya approach Ayanokōji about partnering<\/span><span class=\"meta\">Y2V1 · p.268–271<\/span><\/h3><p class=\"setup\">On the walk back from Keyaki Mall, she and Utomiya Riku (Class 1-C) call out to Ayanokōji; she repeatedly checks her phone (the OAA app).<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> &quot;I&#x27;m Utomiya, and her name is Tsubaki. Could we talk with you for a bit about becoming partners for this special exam?&quot;<span class=\"pg\">p.270<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> &quot;We&#x27;re currently going around searching for upperclassmen with Academic Ability ratings of a C or higher who are willing to cooperate with us.&quot;<span class=\"pg\">p.270<\/span><\/li><li class=\"q narration\">&quot;You&#x27;re Class 2-D&#x27;s… Ayanokōji-senpai, correct?&quot; — Tsubaki<span class=\"pg\">p.270<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> A Class 1-C first-year with a C− Academic rating, still unpaired; she and Utomiya seek a C-or-higher upperclassman, and propose moving to a café to discuss — a timing that strikes Ayanokōji as &quot;far too good to be true.&quot;<span class=\"pg\">p.268–271<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her classmate; he spearheads the conversation and already has a partner.<span class=\"pg\">p.268–271<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him about partnering; he is wary the encounter was arranged.<span class=\"pg\">p.268–271<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-2\">← Before: Epilogue: Seeking a partner<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v2-p258-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka utomiya-riku yagami-takuya tsubaki-sakurako","q":"tsubaki sakurako tsubaki observes  helps contact ayanokoji watches ayanokoji  yagami and kushida from behind in the crowded cafe store  taking a lookout position  later appears with utomiya   is it utomiya  tsubaki helps utomiya contact ayanokoji  she doesn t mention yagami s disclosure to him  and he doesn t mention it to her   both guard their separate contact  tsubaki knew ayanokoji would have been expelled if she d given up on the earlier exam  observant and calculating   quietly monitors the group  orchestrates the introduction to utomiya  and keeps her own counsel about what she knows  brings utomiya to him  neither reveals their separate knowledge  her classmate  helps him contact ayanokoji for the hosen plot  she observed his conversation with ayanokoji without his noticing","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v2-p258-1\"><h3><span class=\"ttl\">Tsubaki observes; helps contact Ayanokōji<\/span><span class=\"meta\">Y2V2 · p.258–270<\/span><\/h3><p class=\"setup\">Watches Ayanokōji, Yagami and Kushida from behind in the crowded café/store, taking a lookout position; later appears with Utomiya.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Is it Utomiya?&quot;<span class=\"pg\">p.264<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Tsubaki helps Utomiya contact Ayanokōji; she doesn&#x27;t mention Yagami&#x27;s disclosure to him, and he doesn&#x27;t mention it to her — both guard their separate contact. Tsubaki knew Ayanokōji would have been expelled if she&#x27;d given up on the earlier exam.<span class=\"pg\">p.264–270<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Observant and calculating — quietly monitors the group, orchestrates the introduction to Utomiya, and keeps her own counsel about what she knows.<span class=\"pg\">p.258–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Brings Utomiya to him; neither reveals their separate knowledge.<span class=\"pg\">p.264–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her classmate; helps him contact Ayanokōji for the Hōsen plot.<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> She observed his conversation with Ayanokōji without his noticing.<span class=\"pg\">p.258<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v2-p351-1\">→ After: Short story: &quot;What Could Be Seen From That Back&quot; — trailing Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v2-p351-1","v":"y2v2","y":2,"o":17,"k":"narration","w":"ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako short story   what could be seen from that back    trailing ayanokoji from her own pov  silently tails ayanokoji back from keyaki mall  proud of her insight intuition  and calls out to him at the convenience store   excuse me   you were tsubaki  right  do you need something from me    ayanokoji  there s something i want to speak to you about  so could you wait outside for a moment  confident in her intuition  she notes he behaves  just like a normal student  yet is sure he noticed her  buys a lollipop to justify the stop and asks to speak outside  probes him about the earlier cafe incident indirectly  trails him  certain he noticed her despite his ordinary demeanor","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v2-p351-1\"><h3><span class=\"ttl\">Short story: &quot;What Could Be Seen From That Back&quot; — trailing Ayanokōji<\/span><span class=\"meta\">Y2V2 · p.351–352<\/span><\/h3><p class=\"setup\">From her own POV, silently tails Ayanokōji back from Keyaki Mall, proud of her insight/intuition, and calls out to him at the convenience store.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Excuse me~~?&quot;<span class=\"pg\">p.351<\/span><\/li><li class=\"q narration\">&quot;You were Tsubaki, right? Do you need something from me?&quot; — Ayanokōji<span class=\"pg\">p.352<\/span><\/li><li class=\"q narration\">&quot;There&#x27;s something I want to speak to you about, so could you wait outside for a moment?&quot;<span class=\"pg\">p.352<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Confident in her intuition, she notes he behaves &quot;just like a normal student&quot; yet is sure he noticed her; buys a lollipop to justify the stop and asks to speak outside; probes him about the earlier café incident indirectly.<span class=\"pg\">p.351–352<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Trails him; certain he noticed her despite his ordinary demeanor.<span class=\"pg\">p.351–352<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v2-p258-1\">← Before: Tsubaki observes; helps contact Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v3-p48-1","v":"y2v3","y":2,"o":18,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki at the start of the island exam she is seen with nishino  ishizaki tries to motivate them  part of ishizaki s group","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v3-p48-1\"><h3><span class=\"ttl\">Tsubaki at the start of the island exam<\/span><span class=\"meta\">Y2V3 · p.48–49<\/span><\/h3><p class=\"setup\">She is seen with Nishino; Ishizaki tries to motivate them.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Part of Ishizaki&#x27;s group.<span class=\"pg\">p.48–49<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v3-p267-1\">→ After: Tsubaki&#x27;s trap: exposing and coercing Yagami<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v3-p267-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"yagami-takuya utomiya-riku kushida-kikyou ayanokouji-kiyotaka housen-kazuomi tsubaki-sakurako","q":"tsubaki sakurako tsubaki s trap  exposing and coercing yagami at 9 pm on day six  the first year reps meet at f9 beach  bonfire signal    tsubaki  the unlikely organizer  takahashi  yagami  utomiya  hosen  absent   well  he doesn t really seem the type to show up on time  or maybe he s just not coming   not for you  sorry  but i m having a hard time believing that   you might even be more obsessed with it than hosen kun and amasawa san   it s the kinda thing i can tell just by looking at you   we gotta take action sooner rather than later   if you don t willingly cooperate starting now  you might end up paying dearly later   someone important to you ll be in danger  or something like that   ah  what s that about kushida senpai  do tell   either you come clean and tell us what you know  or you retire right here  right now  the hidden mastermind   perceptive  eye for people  she deduces yagami s plot to use kushida and that he s obsessed with expelling ayanokoji  uses utomiya s violence to coerce him  threatens kushida  and forces his confession about kushida s past and ayanokoji s knowledge   proving she s been pulling strings from the shadows  sees through his  harmless  act  coerces his confession about kushida  uses him as the muscle  full nelson headlock  to intimidate yagami  knows yagami is connected to her and threatens her to force cooperation  wants him expelled before hosen succeeds  notes he never showed up to the meeting","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v3-p267-1\"><h3><span class=\"ttl\">Tsubaki&#x27;s trap: exposing and coercing Yagami<\/span><span class=\"meta\">Y2V3 · p.267–273<\/span><\/h3><p class=\"setup\">At 9 PM on day six, the first-year reps meet at F9 beach (bonfire signal) — Tsubaki (the unlikely organizer), Takahashi, Yagami, Utomiya, Hōsen (absent).<\/p><p class=\"with\">with <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Well, he doesn&#x27;t really seem the type to show up on time. Or maybe he&#x27;s just not coming.&quot;<span class=\"pg\">p.268<\/span><\/li><li class=\"q spoken\">&quot;Not for you? Sorry, but I&#x27;m having a hard time believing that.&quot;<span class=\"pg\">p.270<\/span><\/li><li class=\"q spoken\">&quot;you might even be more obsessed with it than Hōsen-kun and Amasawa-san.&quot;<span class=\"pg\">p.270<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s the kinda thing I can tell just by looking at you.&quot;<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;we gotta take action sooner rather than later.&quot;<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If you don&#x27;t willingly cooperate starting now, you might end up paying dearly later.&quot;<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;someone important to you&#x27;ll be in danger, or something like that.&quot;<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ah, what&#x27;s that about Kushida-senpai? Do tell.&quot;<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Either you come clean and tell us what you know, or you retire right here, right now.&quot;<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The hidden mastermind — perceptive (&quot;eye for people&quot;), she deduces Yagami&#x27;s plot to use Kushida and that he&#x27;s obsessed with expelling Ayanokōji; uses Utomiya&#x27;s violence to coerce him, threatens Kushida, and forces his confession about Kushida&#x27;s past and Ayanokōji&#x27;s knowledge — proving she&#x27;s been pulling strings from the shadows.<span class=\"pg\">p.267–273<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Sees through his &quot;harmless&quot; act; coerces his confession about Kushida.<span class=\"pg\">p.268–273<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Uses him as the muscle (Full Nelson/headlock) to intimidate Yagami.<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Knows Yagami is connected to her and threatens her to force cooperation.<span class=\"pg\">p.271–272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Wants him expelled before Hōsen succeeds.<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Notes he never showed up to the meeting.<span class=\"pg\">p.268<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v3-p48-1\">← Before: Tsubaki at the start of the island exam<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p127-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi utomiya-riku yagami-takuya nanase-tsubasa ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako tsubaki s siege plan  its failure on day nine  contacts hosen  via nanase and an errand boy katagiri with a walkie talkie  to propose a plan to rescue the sinking first year groups and expel ayanokoji   you already know that  right  four of the last ten groups are freshmen   the head  the brain    her advantage over hosen  we are going to stay together as one in our grade  like all the other students in the upper grades   the organizers of this test have made a proposal  they said they wouldn t mind bringing you down with an act of violence   i will take responsibility for expelling him as the brain that gave instructions to the first graders   it is not that my group has been caught  it is that i have caught the other group  the mastermind   orchestrates the first years  plan to save their own by sinking solo second third years  especially ayanokoji  offering 500 000 points and relying on hosen as the violent one to make the first move  uses multiple gps tablets  including one from ayanokoji s box  and is willing to self destruct  she and her group have points and half price cards  on day 12 her gps trap is countered and hosen is stopped by ryuen   she realizes the plan was doomed from early on  recruits him as the violent muscle  he only pretends to follow  her class 1 c partner  keeps secrets from him  fellow plotter  offers  insurance  with reserve tablets  questions whether she s on their side  nanase is secretly ayanokoji s ally  her target  her siege is thwarted","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p127-1\"><h3><span class=\"ttl\">Tsubaki&#x27;s siege plan; its failure<\/span><span class=\"meta\">Y2V4 · p.127–139, 152–185<\/span><\/h3><p class=\"setup\">On day nine, contacts Hōsen (via Nanase and an errand boy Katagiri with a walkie-talkie) to propose a plan to rescue the sinking first-year groups and expel Ayanokōji.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;You already know that, right? Four of the last ten groups are freshmen.&quot;<span class=\"pg\">p.131<\/span><\/li><li class=\"q spoken\">&quot;The head, the brain.&quot; — her advantage over Hōsen<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\">&quot;we are going to stay together as one in our grade, like all the other students in the upper grades.&quot;<span class=\"pg\">p.135<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;The organizers of this test have made a proposal. They said they wouldn&#x27;t mind bringing you down with an act of violence.&quot;<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I will take responsibility for expelling him as the brain that gave instructions to the first graders.&quot;<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It is not that my group has been caught, it is that I have caught the other group.&quot;<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The mastermind — orchestrates the first-years&#x27; plan to save their own by sinking solo second/third-years (especially Ayanokōji), offering 500,000 points and relying on Hōsen as the violent one to make the first move; uses multiple GPS tablets (including one from Ayanokōji&#x27;s box) and is willing to self-destruct (she and her group have points and half-price cards); on day 12 her GPS trap is countered and Hōsen is stopped by Ryūen — she realizes the plan was doomed from early on.<span class=\"pg\">p.127–185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Recruits him as the violent muscle; he only pretends to follow.<span class=\"pg\">p.127–168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her Class 1-C partner; keeps secrets from him.<span class=\"pg\">p.130–138<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Fellow plotter; offers &quot;insurance&quot; with reserve tablets.<span class=\"pg\">p.141–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Questions whether she&#x27;s on their side; Nanase is secretly Ayanokōji&#x27;s ally.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her target; her siege is thwarted.<span class=\"pg\">p.152–185<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4_5-p254-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki  the utomiya sakayanagi angle yagami  explaining how he created a common enemy   he was thinking that he would definitely stop it the next time  to team up with another class who originally wouldn t join hands with you  the quickest and easiest method was to create a common enemy  hosen  i got into the pockets of tsubaki and utomiya   a common enemy  hosen  yagami s account reaches beyond this volume s exam   tsubaki was drawn into his scheme  no on page presence  no lines  no direct action attributed beyond yagami s summary","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4_5-p254-1\"><h3><span class=\"ttl\">Tsubaki: the Utomiya–Sakayanagi angle<\/span><span class=\"meta\">Y2V4.5 · p.254<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Yagami, explaining how he created a common enemy: &quot;…He was thinking that he would definitely stop it the next time. To team up with another class who originally wouldn&#x27;t join hands with you, the quickest and easiest method was to create a common enemy, Hōsen. I got into the pockets of Tsubaki and Utomiya…&quot;; &quot;a common enemy, Hōsen.&quot;<span class=\"pg\">p.254–255<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Yagami&#x27;s account reaches beyond this volume&#x27;s exam — Tsubaki was drawn into his scheme; no on-page presence; no lines; no direct action attributed beyond Yagami&#x27;s summary.<span class=\"pg\">p.254<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-tsubaki-sakurako-y2v7-p191-1","v":"y2v7","y":2,"o":23,"k":"","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako tsubaki sakurako s white room play  2   after the festival ends  utomiya waits outside the school with tsubaki  ak receives a phone call from an unknown number at the classroom  the voice sounds familiar   tsubaki sakurako  a student in first year class c   hello    ayanokoji answers his phone   are you still in school  i d like to talk to you for a minute if you d like    the caller  the voice sounds familiar   are you alone now    ayanokoji   unfortunately not    the caller   then why don t we meet up    the caller   where are you    ayanokoji   i just left the front door  you re still on campus  right    the caller   give me five minutes    ayanokoji   okay    the caller  after a short call  he told horikita   i m sorry  but i m going to have to step out for a bit i ll be back in about 10 or 20 minutes  then we ll continue our conversation    he returned to the classroom to finish the conversation  horikita   okay  i ll wait here    she agrees to wait   2    is tsubaki alone at the meeting place    he thought so for a moment  but it seemed that utomiya was talking to someone a little farther away  he was only looking at them   is there something you re having trouble communicating over the phone    tsubaki asks ayanokoji  who was holding the phone   well  the first year students are in a bit of a mess right now  there was an unexpected expulsion at the school festival    tsubaki   expelled  that s a very disturbing story    ayanokoji  someone else was involved in this school expulsion fiasco  that was tsubaki sakurako  who was in front of him then   i m satisfied with the result  which is more than i imagined ayanokoji senpai    tsubaki   tsubaki made a circle with her finger as if to say   you passed    the narration   it seems you ve successfully extracted information from sato senpai and drove yagami kun out of school  i am very grateful    tsubaki  sato was apparently approached by tsubaki near the women s restroom at keyaki mall  there  she flashed some bait that would turn things around for her  including a turnaround between his relationship with kei  which tickled her curiosity  she intensified the threats gradually over days because sato would eventually come to consult someone  and that would be him  the goal was not to cage sato  but to wait for her to ask him for help  ayanokoji to tsubaki   it seems you called sato to your room and made cheap threats  but it wasn t a serious attempt to manipulate her into ruining our relationship  it was because you wanted to push her to act  or deal with the threat of kei s relationship  by indirectly letting her know that we were getting close  tsubaki listened silently  staring at him without denial  ayanokoji   then  you most likely told sato that it was yagami who was behind the threats  not you  tsubaki played dumb   i don t know what that means  what a surprise   as soon as you saw that sato wouldn t accept your invitation  you contacted her again as if to follow up and made similar comments and provoked her  when you saw that sato didn t seem to have consulted anyone  you gradually intensified your threats and hounded her  this was due to the fact that she would eventually come to consult someone  and that would be me    ayanokoji s read of the three week squeeze   yagami kun is a bad guy  isn t he    tsubaki   you don t need cheap theatrics  yagami had nothing to do with this  he s not involved    ayanokoji   you don t think it was actually yagami kun s order    tsubaki  the only people who know about karuizawa s past are those who are connected with the white room  others can t easily imitate him  tsubaki   then isn t it the other way around  you found out that i was trying to frame yagami kun  didn t you  and yet you did nothing against me and even expelled yagami kun  who might be innocent  isn t that contradictory  there was no indication that ayanokoji senpai was looking into it in detail  ayanokoji   ah  i didn t investigate tsubaki or yagami  no need for that  tsubaki   what do you mean  ayanokoji   i m sorry  but i don t feel like talking any more    he was convinced that he had said enough  it wasn t even tsubaki who was manipulating everything  furthermore  the person lurking in the background was the one who painted this picture   utomiya kun  can you come here for a minute    tsubaki beckoned to utomiya  who was on the phone  and instructed him to hand his cell phone to ayanokoji   go ahead    wary  utomiya handed the phone to him while it was still connected  the voice of the man he spoke to last year on the phone and in front of his room   yagami had some of tsubaki s and utomiya s classmates expelled  that s why those two worked together with me  the man on the phone continued   you left him alone because you knew you could take him down at any time if you moved directly on him  but as a result  there were expulsions from the first year  it wouldn t have happened if it hadn t been for his nuisance  ayanokoji   i don t deny it  the man on the phone   the only way to avoid further unnecessary sacrifices was to have him expelled  but even if you knew that  it isn t easy to defeat yagami  i know he is no ordinary high school student  ayanokoji   that s why you wanted to use me    he made this decision because he understood the white room student s purpose and obsession  the man on the phone   eventually  you ll get in touch with someone close to me  and when that happens  there will be expulsions  right  the phone man s line continues from p 196   that s right  but to drive yagami into a corner and expel him all at once  closes the previous page and  that was a little out of the calculations  did you not take into account the possibility that yagami was unrelated  is printed on p 197   two verbatim fragments split at the page turn  kept as printed  continuation kept in this file as separate rows rather than as one spliced quotation  the man on the phone   it was up to yagami s choice whether or not he wanted to be expelled  it wasn t me who decided whether it was black or white  he was playing with fire here and there  just like he expelled a student from 1st year c  he contacted kushida kikyo  pretending to be her former junior  and he used the information he was given to control and manipulate her  he provoked unrelated students on a deserted island by inflicting serious injuries to them  he also checked the contents of a love letter for another person  thinking it was a trap  i don t know why horikita and ibuki were there  but i think it was also because he was playing with fire   so it was all connected    the man on the phone   that guy didn t realize he was strangling himself with cotton wool    the man on the phone   surely if yagami hadn t done anything  he wouldn t have been expelled at this stage    the man on the phone  ayanokoji   i agree  the man on the phone   the only reason he was expelled was because yagami admitted to himself that he was black  he merely set up the stage for a test  if he was completely white  there would ve been no fuss in the first place  he only went to the student council room because he knew him and because he was smart  the man on the phone   you seem to be as good as the rumors say you are  the man on the phone   by the way  just to confirm  remember what you told me before  you told me that if i didn t get rid of the people who were in my way  i wouldn t expect peace and quiet to return  that was a bluff  wasn t it  you wanted to create a sense of urgency that if i didn t take care of the problem soon  it would become even more difficult  in order to make him move  he had made a move to get yagami expelled from the school from that stage  the man on the phone   ayanokoji sensei was right  you were right to choose this school  ayanokoji   what do you mean  the man on the phone   it s just as you believe  i m going to enjoy my school life  and as long as we don t bump into each other during the first and second years squabbles  i ll let our relationship end here  he said what he wanted to say and the call was unilaterally hung up  a sneak peek at the cell phone screen revealed that the call was deliberately blocked  this was done because they didn t want utomiya to realize from their address or phone number that they were registered to an address  tsubaki   have you figured it out  ayanokoji   yeah  ayanokoji   don t quit just because you ve defeated your enemy  tsubaki  tsubaki   i know  to be honest  i wasn t attached to this school at first  but that s changed a bit  this school is surprisingly fun  looking at the exchange just now  it was clear that there were a lot of mixed feelings other than simply taking revenge on an enemy  tsubaki   so  we re leaving  utomiya  forcing himself to pull out the honorific   senpai    returned to the dormitory with tsubaki  ayanokoji   i should get back to class too   there was an unexpected expulsion at the school festival    the school festival expelled someone  the person in front of him is tsubaki sakurako   i m satisfied with the result  which is more than i imagined ayanokoji senpai  utomiya is with tsubaki at the meeting  he hands his phone over   senpai  she works with him against yagami  she reports the expulsion  she leaves the school","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v7-p191-1\"><h3><span class=\"ttl\">Tsubaki Sakurako&#x27;s White Room play<\/span><span class=\"meta\">Y2V7 · p.191–199<\/span><\/h3><p class=\"setup\">§2 — after the festival ends; Utomiya waits outside the school with Tsubaki; AK receives a phone call from an unknown number at the classroom; the voice sounds familiar — Tsubaki Sakurako, a student in first-year Class C.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>65 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Hello?” — Ayanokōji answers his phone.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Are you still in school? I&#x27;d like to talk to you for a minute if you&#x27;d like.” — the caller; the voice sounds familiar.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Are you alone now?” — Ayanokōji.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Unfortunately not.” — the caller.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Then why don&#x27;t we meet up?” — the caller.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Where are you?” — Ayanokōji.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I just left the front door. You&#x27;re still on campus, right?” — the caller.<span class=\"pg\">p.191–192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Give me five minutes.” — Ayanokōji.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Okay.” — the caller.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> After a short call, he told Horikita: “I&#x27;m sorry, but I&#x27;m going to have to step out for a bit…I&#x27;ll be back in about 10 or 20 minutes. Then we&#x27;ll continue our conversation.” — he returned to the classroom to finish the conversation.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Horikita: “Okay, I&#x27;ll wait here.” — she agrees to wait.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> §2 — “Is Tsubaki alone at the meeting place?” — he thought so for a moment, but it seemed that Utomiya was talking to someone a little farther away; he was only looking at them.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Is there something you&#x27;re having trouble communicating over the phone?” — Tsubaki asks Ayanokōji, who was holding the phone.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Well, the first-year students are in a bit of a mess right now. There was an unexpected expulsion at the school festival.” — Tsubaki.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Expelled? That&#x27;s a very disturbing story.” — Ayanokōji.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Someone else was involved in this school expulsion fiasco; that was Tsubaki Sakurako, who was in front of him then; “I&#x27;m satisfied with the result, which is more than I imagined…Ayanokōji-senpai.” — Tsubaki.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Tsubaki made a circle with her finger as if to say, ‘you passed.’” — the narration; “It seems you&#x27;ve successfully extracted information from Satō-senpai and drove Yagami-kun out of school. I am very grateful.” — Tsubaki.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Satō was apparently approached by Tsubaki near the women&#x27;s restroom at Keyaki Mall; there, she flashed some bait that would turn things around for her, including a turnaround between his relationship with Kei, which tickled her curiosity; she intensified the threats gradually over days because Satō would eventually come to consult someone, and that would be him; the goal was not to cage Satō, but to wait for her to ask him for help.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji to Tsubaki: “It seems you called Satō to your room and made cheap threats, but it wasn&#x27;t a serious attempt to manipulate her into ruining our relationship. It was because you wanted to push her to act, or deal with the threat of Kei&#x27;s relationship, by indirectly letting her know that we were getting close.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki listened silently, staring at him without denial.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Then, you most likely told Satō that it was Yagami who was behind the threats, not you.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki played dumb: “I don&#x27;t know what that means. What a surprise.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “As soon as you saw that Satō wouldn&#x27;t accept your invitation, you contacted her again as if to follow up and made similar comments and provoked her. When you saw that Satō didn&#x27;t seem to have consulted anyone, you gradually intensified your threats and hounded her. This was due to the fact that she would eventually come to consult someone, and that would be me.” — Ayanokōji&#x27;s read of the three-week squeeze.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Yagami-kun is a bad guy, isn&#x27;t he?” — Tsubaki.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “You don&#x27;t need cheap theatrics. Yagami had nothing to do with this. He&#x27;s not involved.” — Ayanokōji.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “You don&#x27;t think it was actually Yagami-kun&#x27;s order?” — Tsubaki.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The only people who know about Karuizawa&#x27;s past are those who are connected with the White Room; others can&#x27;t easily imitate him.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “Then isn&#x27;t it the other way around, you found out that I was trying to frame Yagami-kun, didn&#x27;t you? And yet you did nothing against me and even expelled Yagami-kun, who might be innocent. Isn&#x27;t that contradictory? There was no indication that Ayanokōji-senpai was looking into it in detail.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Ah. I didn&#x27;t investigate Tsubaki or Yagami. No need for that.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “What do you mean?”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I&#x27;m sorry, but I don&#x27;t feel like talking any more.” — he was convinced that he had said enough; it wasn&#x27;t even Tsubaki who was manipulating everything; furthermore, the person lurking in the background was the one who painted this picture.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Utomiya-kun, can you come here for a minute?” — Tsubaki beckoned to Utomiya, who was on the phone, and instructed him to hand his cell phone to Ayanokōji.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Go ahead...” — Wary, Utomiya handed the phone to him while it was still connected.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The voice of the man he spoke to last year on the phone and in front of his room: “Yagami had some of Tsubaki&#x27;s and Utomiya&#x27;s classmates expelled. That&#x27;s why those two worked together with me.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone continued: “You left him alone because you knew you could take him down at any time if you moved directly on him. But as a result, there were expulsions from the first year. It wouldn&#x27;t have happened if it hadn&#x27;t been for his nuisance.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I don&#x27;t deny it.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “The only way to avoid further unnecessary sacrifices was to have him expelled. But even if you knew that, it isn&#x27;t easy to defeat Yagami. I know he is no ordinary high school student.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “That&#x27;s why you wanted to use me.” — he made this decision because he understood the white room student&#x27;s purpose and obsession.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “Eventually, you&#x27;ll get in touch with someone close to me. And when that happens, there will be expulsions, right?”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The phone man&#x27;s line continues from p.196: “That&#x27;s right. But to drive Yagami into a corner and expel him all at once?” closes the previous page and “That was a little out of the calculations. Did you not take into account the possibility that Yagami was unrelated?” is printed on p.197 — two verbatim fragments split at the page turn; kept as printed. Continuation kept in this file as separate rows rather than as one spliced quotation.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “It was up to Yagami&#x27;s choice whether or not he wanted to be expelled. It wasn&#x27;t me who decided whether it was black or white. He was playing with fire here and there, just like he expelled a student from 1st year C. He contacted Kushida Kikyo, pretending to be her former junior, and he used the information he was given to control and manipulate her. He provoked unrelated students on a deserted island by inflicting serious injuries to them. He also checked the contents of a love letter for another person, thinking it was a trap. I don&#x27;t know why Horikita and Ibuki were there, but I think it was also because he was playing with fire.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “So it was all connected.” — the man on the phone.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “That guy didn&#x27;t realize he was strangling himself with cotton wool.” — the man on the phone.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Surely if Yagami hadn&#x27;t done anything, he wouldn&#x27;t have been expelled at this stage.” — the man on the phone.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I agree.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “The only reason he was expelled was because Yagami admitted to himself that he was black.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He merely set up the stage for a test; if he was completely white, there would&#x27;ve been no fuss in the first place; he only went to the student council room because he knew him and because he was smart.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “You seem to be as good as the rumors say you are.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “By the way, just to confirm, remember what you told me before? You told me that if I didn&#x27;t get rid of the people who were in my way, I wouldn&#x27;t expect peace and quiet to return. That was a bluff, wasn&#x27;t it? You wanted to create a sense of urgency that if I didn&#x27;t take care of the problem soon, it would become even more difficult.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> In order to make him move, he had made a move to get Yagami expelled from the school from that stage.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “Ayanokōji-sensei was right, you were right to choose this school.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “What do you mean?”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “It&#x27;s just as you believe, I&#x27;m going to enjoy my school life, and as long as we don&#x27;t bump into each other during the first and second years squabbles, I&#x27;ll let our relationship end here.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He said what he wanted to say and the call was unilaterally hung up; a sneak peek at the cell phone screen revealed that the call was deliberately blocked; this was done because they didn&#x27;t want Utomiya to realize from their address or phone number that they were registered to an address.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “Have you figured it out?”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Yeah.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Don&#x27;t quit just because you&#x27;ve defeated your enemy, Tsubaki.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “I know. To be honest, I wasn&#x27;t attached to this school at first, but that&#x27;s changed a bit. This school is surprisingly fun.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Looking at the exchange just now, it was clear that there were a lot of mixed feelings other than simply taking revenge on an enemy.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “So, we&#x27;re leaving.”<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Utomiya, forcing himself to pull out the honorific: “Senpai.” — returned to the dormitory with Tsubaki.<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I should get back to class too.”<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There was an unexpected expulsion at the school festival.” — the school festival expelled someone; the person in front of him is Tsubaki Sakurako; “I&#x27;m satisfied with the result, which is more than I imagined…Ayanokōji-senpai.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Utomiya is with Tsubaki at the meeting; he hands his phone over; “Senpai.”<span class=\"pg\">p.191–199<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She works with him against Yagami; she reports the expulsion; she leaves the school.<span class=\"pg\">p.191–199<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p46-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 2  group 20 s first year class c at the inn  kiyotaka reads the group 20 roster  named as a first year class c member of group 20  tsubaki sakurako  shintoku taro  kiyotaka hardly knows the first years apart from tsubaki","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p46-1\"><h3><span class=\"ttl\">Ch.2: Group 20&#x27;s first-year Class C<\/span><span class=\"meta\">Y2V11 · p.46<\/span><\/h3><p class=\"setup\">At the inn, Kiyotaka reads the Group 20 roster.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Named as a first-year Class C member of Group 20: Tsubaki Sakurako, Shintoku Taro.<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kiyotaka hardly knows the first-years apart from Tsubaki.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p137-1\">→ After: Ch.5: Surprisingly enthusiastic<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p137-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 5  surprisingly enthusiastic the girls  shared room  the first years get drawn into the card game   it seemed that the other first year students  tsubaki included  were surprisingly enthusiastic    unattributed narration  she is expected to be shy  she is not  named in the room s enthusiasm  not separately quoted on these pages","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p137-1\"><h3><span class=\"ttl\">Ch.5: Surprisingly enthusiastic<\/span><span class=\"meta\">Y2V11 · p.137–140<\/span><\/h3><p class=\"setup\">The girls&#x27; shared room; the first-years get drawn into the card game.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “it seemed that the other first-year students, Tsubaki included, were surprisingly enthusiastic.” — unattributed narration; she is expected to be shy; she is not.<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in the room&#x27;s enthusiasm; not separately quoted on these pages.<span class=\"pg\">p.137<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p46-1\">← Before: Ch.2: Group 20&#x27;s first-year Class C<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p142-1\">→ After: Ch.5: The cute one<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p142-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 5  the cute one on the way to the rooms  the first year boys buzz about girls  rooms  tsubaki makes an impression   and wasn t tsubaki san cute    untagged first year  tsubaki is a first year of their group  the boys gawk","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p142-1\"><h3><span class=\"ttl\">Ch.5: The cute one<\/span><span class=\"meta\">Y2V11 · p.142<\/span><\/h3><p class=\"setup\">On the way to the rooms; the first-year boys buzz about girls&#x27; rooms; Tsubaki makes an impression.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “And wasn&#x27;t Tsubaki-san cute?” — untagged first-year; Tsubaki is a first-year of their group; the boys gawk.<span class=\"pg\">p.142<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p137-1\">← Before: Ch.5: Surprisingly enthusiastic<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p152-1\">→ After: Ch.6: The shogi five<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p152-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 6  the shogi five the shogi lineup  she is named in it   the participants kiryuin chose were me  morishita  hashimoto  hiyori  and tsubaki    she is picked for the shogi match  she is in the room  named in narration  not present in the shogi scene","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p152-1\"><h3><span class=\"ttl\">Ch.6: The shogi five<\/span><span class=\"meta\">Y2V11 · p.152<\/span><\/h3><p class=\"setup\">The shogi lineup; she is named in it.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “The participants Kiryūin chose were me, Morishita, Hashimoto, Hiyori, and Tsubaki.” — she is picked for the shogi match; she is in the room.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in narration; not present in the shogi scene.<span class=\"pg\">p.152<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p142-1\">← Before: Ch.5: The cute one<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p182-1\">→ After: Ch.8: The walk in the cold<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p182-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi tsubaki-sakurako","q":"tsubaki sakurako ch 8  the walk in the cold sunday  fourth day  the camp ends today  she spots him in the dim lobby  they walk outside into the cold  the rematch with amasawa is set for 7 o clock  she heard from hashimoto senpai that he gets up early  she doesn t change her attitude toward anyone  her smile  if any  is rare   it s still quite early in the morning after all  isn t it   for the past two days  i heard from hashimoto senpai that you ve been getting up early in the morning   so  you came looking for me   not so much looking for you  but i just thought i d check if you were here   but if you were here  that would change things quite a bit   i don t think there s any reason for you to come see me anymore  the special exam given only to first year students has been canceled   i wasn t interested in the prize money from the start  but i m disappointed  i m lamenting the loss of the right to expel you in a dignified manner   that s dangerous talk  i don t remember you ever resenting me   don t you think there are more things you don t realize  people unknowingly incur resentment  you know   i can t tell if you re joking or serious   someone might come here  so why don t we take a walk   it s still dark outside   i thought it would be snowing quite a bit in the mountains of tochigi  but it s not as much as i thought   february has a drastic temperature difference  maybe it s because we ve had a few warm days recently   do you like snow  senpai   i don t particularly like or dislike it  i just think i enjoy the scenery when it snows  do you like snow  tsubaki   i guess i do  at least more than you  senpai   can you look at this   being in this school feels like being cut off from the outside world  doesn t it  who do you want to see first when you graduate next year  senpai   you ask strange questions   probably just my family   family  anyone else   not really  i don t have any close friends  so that s about it   i see  then  can i ask you one more strange question   imagine if you had a brother  and you didn t know about his existence because your parents hid it from you for years  but one day  you were told he was actually family  would you be able to love him as a family member  of course  assuming there is a genuine blood connection   that s a difficult question   i see  i think i would probably feel the same way as you  but  if i knew that the other person had special circumstances and a sad past  i would want to grow closer  i would like to know more about my sister  who i had been separated from   i might not feel anything  of course  i think it would greatly depend on the other person s personality and situation  her hypothetical   a hidden sibling kept secret for years  the way she frames it  my sister  who i had been separated from  strongly suggests personal experience  the brother sister switch is a deliberate evasion   i am confused  ayanokoji senpai  from this school    the sentence is intentionally vague and fragmented  she stops mid sentence when horikita  ibuki and kushida appear   we ve been interrupted  let s talk again later  she tests him with the sibling hypothetical  her real subject is never named on these pages  she heard from him that he rises early  she knows more than she lets on","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p182-1\"><h3><span class=\"ttl\">Ch.8: The walk in the cold<\/span><span class=\"meta\">Y2V11 · p.182–185<\/span><\/h3><p class=\"setup\">Sunday, fourth day; the camp ends today; she spots him in the dim lobby; they walk outside into the cold; the rematch with Amasawa is set for 7 o&#x27;clock.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It&#x27;s still quite early in the morning after all, isn&#x27;t it?”<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\">“For the past two days, I heard from Hashimoto-senpai that you&#x27;ve been getting up early in the morning.”<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “So, you came looking for me?”<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>31 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She heard from Hashimoto-senpai that he gets up early; she doesn&#x27;t change her attitude toward anyone; her smile, if any, is rare.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not so much looking for you, but I just thought I&#x27;d check if you were here.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But if you were here, that would change things quite a bit.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think there&#x27;s any reason for you to come see me anymore. The special exam given only to first-year students has been canceled.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wasn&#x27;t interested in the prize money from the start, but I&#x27;m disappointed. I&#x27;m lamenting the loss of the right to expel you in a dignified manner.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s dangerous talk. I don&#x27;t remember you ever resenting me.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t you think there are more things you don&#x27;t realize? People unknowingly incur resentment, you know?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can&#x27;t tell if you&#x27;re joking or serious.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Someone might come here, so why don&#x27;t we take a walk?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s still dark outside.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought it would be snowing quite a bit in the mountains of Tochigi, but it&#x27;s not as much as I thought.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “February has a drastic temperature difference. Maybe it&#x27;s because we&#x27;ve had a few warm days recently.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you like snow, Senpai?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t particularly like or dislike it. I just think I enjoy the scenery when it snows. Do you like snow, Tsubaki?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...I guess I do. At least more than you, Senpai.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you look at this?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Being in this school feels like being cut off from the outside world, doesn&#x27;t it? Who do you want to see first when you graduate next year, Senpai?”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You ask strange questions.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Probably just my family.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Family... Anyone else?”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not really. I don&#x27;t have any close friends, so that&#x27;s about it.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see... Then, can I ask you one more strange question?”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Imagine if you had a brother, and you didn&#x27;t know about his existence because your parents hid it from you for years. But one day, you were told he was actually family, would you be able to love him as a family member? Of course, assuming there is a genuine blood connection.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s a difficult question.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. I think I would probably feel the same way as you. But, if I knew that the other person had special circumstances and a sad past, I would want to grow closer. I would like to know more about my sister, who I had been separated from.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I might not feel anything. Of course, I think it would greatly depend on the other person&#x27;s personality and situation.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her hypothetical — a hidden sibling kept secret for years; the way she frames it (“my sister, who I had been separated from”) strongly suggests personal experience; the brother-sister switch is a deliberate evasion.<span class=\"pg\">p.184–185<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I am confused. Ayanokōji-senpai, from this school—” — the sentence is intentionally vague and fragmented; she stops mid-sentence when Horikita, Ibuki and Kushida appear.<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We&#x27;ve been interrupted... Let&#x27;s talk again later.”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She tests him with the sibling hypothetical; her real subject is never named on these pages.<span class=\"pg\">p.182–185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> She heard from him that he rises early; she knows more than she lets on.<span class=\"pg\">p.182–183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p152-1\">← Before: Ch.6: The shogi five<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki sakurako mentioned in passing named in this volume  passing mention  locator pages  p 28  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v12-p12-1\"><h3><span class=\"ttl\">tsubaki-sakurako mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.28; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-tsubaki-sakurako-y3v2-p257-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"utomiya-riku housen-kazuomi nanase-tsubasa amasawa-ichika yagami-takuya ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako  the six first year students  the plot against ayanokoji tsubaki and utomiya watch second year ayanokoji from a cafe  tsubaki asks if utomiya wants to move up to class a   tsubaki  do you want to move up to class a    utomiya  not really   it s housen and nanase   his actual fighting ability is unknown  but i can t imagine him losing to someone at housen s level   i think i ve become a little interested in getting to know you  utomiya kun    tsubaki  stop it  i don t pry into anyone s business  and i don t want anyone prying into mine    utomiya  either way  we re enemies    yagami hosen and nanase  first year class d  pass ayanokoji with only a polite nod from nanase  utomiya notices a bandage on ayanokoji s left hand and suspects a clash with hosen  utomiya rates ayanokoji far above hosen    everyone around him is weak    and dismisses hosen s rampages as because of weak opponents  amasawa  first year class a  teases the two about dating and leaves a blown kiss  she  takahashi and ishigami know of the special exam in class a  yagami joins  drawn by the  whole other level  of private points  utomiya  tsubaki  hosen  nanase  yagami and amasawa all target ayanokoji   a  baffling exam  targeting a specific individual  from this gathering the story connects to the upcoming uninhabited island special exam  tsubaki s cafe companion  both lack interest in class a special privileges  he is wary of prying  first year class d  utomiya suspects he may have clashed with ayanokoji and rates him low  first year class d  gave ayanokoji a polite nod  first year class a  teases tsubaki and utomiya and is involved in the first year special exam  first year class b  joins the conversation  drawn by the private points  the target of all six first years  they watch him and the bandage on his hand","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y3v2-p257-1\"><h3><span class=\"ttl\">&quot;The Six First-Year Students&quot;: the plot against Ayanokōji<\/span><span class=\"meta\">Y3V2 · p.257–260<\/span><\/h3><p class=\"setup\">Tsubaki and Utomiya watch second-year Ayanokōji from a cafe; Tsubaki asks if Utomiya wants to move up to Class A.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Tsubaki, do you want to move up to Class A?&quot; — Utomiya<span class=\"pg\">p.257<\/span><\/li><li class=\"q spoken\">&quot;Not really.&quot;<span class=\"pg\">p.257<\/span><\/li><li class=\"q spoken\">&quot;It&#x27;s Housen and Nanase.&quot;<span class=\"pg\">p.257<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;His actual fighting ability is unknown, but I can&#x27;t imagine him losing to someone at Housen&#x27;s level.&quot;<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I think I&#x27;ve become a little interested in getting to know you, Utomiya-kun.&quot; — Tsubaki<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Stop it. I don&#x27;t pry into anyone&#x27;s business, and I don&#x27;t want anyone prying into mine.&quot; — Utomiya<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Either way, we&#x27;re enemies.&quot; — Yagami<span class=\"pg\">p.259<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Hōsen and Nanase (first-year Class D) pass Ayanokōji with only a polite nod from Nanase; Utomiya notices a bandage on Ayanokōji&#x27;s left hand and suspects a clash with Hōsen.<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Utomiya rates Ayanokōji far above Hōsen — &quot;everyone around him is weak&quot; — and dismisses Hōsen&#x27;s rampages as because of weak opponents.<span class=\"pg\">p.257–258<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Amasawa (first-year Class A) teases the two about dating and leaves a blown kiss; she, Takahashi and Ishigami know of the special exam in Class A. Yagami joins, drawn by the &quot;whole other level&quot; of Private Points.<span class=\"pg\">p.258–259<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Utomiya, Tsubaki, Hōsen, Nanase, Yagami and Amasawa all target Ayanokōji — a &quot;baffling exam&quot; targeting a specific individual; from this gathering the story connects to the upcoming uninhabited-island special exam.<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Tsubaki&#x27;s cafe companion; both lack interest in Class A/special privileges; he is wary of prying.<span class=\"pg\">p.257–260<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> First-year Class D; Utomiya suspects he may have clashed with Ayanokōji and rates him low.<span class=\"pg\">p.257–258<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> First-year Class D; gave Ayanokōji a polite nod.<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> First-year Class A; teases Tsubaki and Utomiya and is involved in the first-year special exam.<span class=\"pg\">p.258–259<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> First-year Class B; joins the conversation, drawn by the Private Points.<span class=\"pg\">p.259–260<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The target of all six first-years; they watch him and the bandage on his hand.<span class=\"pg\">p.257–260<\/span><\/li><\/ul><\/details><\/article>"}];
